bool DeviceInfo::validateJsonForCreation(const Json::Value &pJson, std::string &err)
{

    if(pJson.isMember("id"))
    {
        if(!validJsonOfField(0, "id", pJson["id"], err, true))
            return false;
    }

    if(pJson.isMember("user_id"))
    {
        if(!validJsonOfField(1, "user_id", pJson["user_id"], err, true))
            return false;
    }

    else
    {
        err="The user_id column cannot be null";
        return false;
    }

    if(pJson.isMember("ip_address"))
    {
        if(!validJsonOfField(2, "ip_address", pJson["ip_address"], err, true))
            return false;
    }

    if(pJson.isMember("device_name"))
    {
        if(!validJsonOfField(3, "device_name", pJson["device_name"], err, true))
            return false;
    }

    if(pJson.isMember("device_os"))
    {
        if(!validJsonOfField(4, "device_os", pJson["device_os"], err, true))
            return false;
    }

    if(pJson.isMember("device_type"))
    {
        if(!validJsonOfField(5, "device_type", pJson["device_type"], err, true))
            return false;
    }

    if(pJson.isMember("access_token"))
    {
        if(!validJsonOfField(6, "access_token", pJson["access_token"], err, true))
            return false;
    }

    if(pJson.isMember("refresh_token"))
    {
        if(!validJsonOfField(7, "refresh_token", pJson["refresh_token"], err, true))
            return false;
    }

    if(pJson.isMember("created_at"))
    {
        if(!validJsonOfField(8, "created_at", pJson["created_at"], err, true))
            return false;
    }

    return true;
}
